537	class _TabBar extends StatelessWidget {
538	  const _TabBar({required this.activeTab, required this.isSaving});
539	
540	  final CaptureTab activeTab;
541	
542	  /// Review finding: a save already in flight must disable the tab bar —
543	  /// without this, switching tabs mid-save let that stale `save()` call's
544	  /// eventual `TextEntrySaved`/`TextEntryError` land against a tab/text
545	  /// the user has since left (popping the modal unexpectedly, or showing
546	  /// an error nobody is looking at). `TextEntryCubit.selectTab` also
547	  /// guards against this independently — this is the UI-level half of
548	  /// that same fix.
549	  final bool isSaving;
550	
551	  static const _tabs = [
552	    (CaptureTab.texto, 'Texto'),
553	    (CaptureTab.audio, 'Áudio'),
554	    (CaptureTab.foto, 'Foto'),
555	  ];
556	
557	  @override
558	  Widget build(BuildContext context) {
559	    return Row(
560	      children: [
561	        for (var i = 0; i < _tabs.length; i++) ...[
562	          Expanded(
563	            child: _TabButton(
564	              tab: _tabs[i].$1,
565	              label: _tabs[i].$2,
566	              isActive: _tabs[i].$1 == activeTab,
567	              isSaving: isSaving,
568	            ),
569	          ),
570	          if (i < _tabs.length - 1)
571	            const SizedBox(width: DesignTokens.spacingSm),
572	        ],
573	      ],
574	    );
575	  }
576	}
577	
578	class _TabButton extends StatelessWidget {
579	  const _TabButton({
580	    required this.tab,
581	    required this.label,
582	    required this.isActive,
583	    required this.isSaving,
584	  });
585	
586	  final CaptureTab tab;
587	  final String label;
588	  final bool isActive;
589	  final bool isSaving;
590	
