1186	/// renders a static placeholder pattern at [opacity] instead of
1187	/// subscribing — the "frozen" rendering `_AudioProcessingView` uses.
1188	class _Waveform extends StatefulWidget {
1189	  const _Waveform({required this.amplitudeStream, required this.opacity});
1190	
1191	  final Stream<double>? amplitudeStream;
1192	  final double opacity;
1193	
1194	  @override
1195	  State<_Waveform> createState() => _WaveformState();
