1198	class _WaveformState extends State<_Waveform> {
1199	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
1200	  // on every new amplitude sample, which `List.filled`'s own default
1201	  // fixed-length list doesn't support.
1202	  final List<double> _samples = List.filled(
1203	    _waveformBarCount,
1204	    0.1,
1205	    growable: true,
1206	  );
1207	  StreamSubscription<double>? _subscription;
1208	
1209	  @override
1210	  void initState() {
1211	    super.initState();
1212	    _subscription = widget.amplitudeStream?.listen(
1213	      (amplitude) {
1214	        if (!mounted) {
1215	          return;
1216	        }
1217	        setState(() {
1218	          _samples.removeAt(0);
1219	          // `num.clamp` returns `num`, not `double` — `_samples` is
1220	          // `List<double>`.
1221	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
1222	        });
1223	      },
1224	      // Review finding: an unhandled `onError` turns a native amplitude-
1225	      // stream error into an uncaught async exception — the waveform
1226	      // just stays frozen on its last sample instead, no worse than the
1227	      // already-handled "no live stream" (frozen/processing) case.
1228	      onError: (_) {},
1229	    );
1230	  }
1231	
1232	  @override
1233	  void dispose() {
1234	    _subscription?.cancel();
1235	    super.dispose();
1236	  }
1237	
1238	  @override
1239	  Widget build(BuildContext context) {
1240	    return Opacity(
1241	      opacity: widget.opacity,
1242	      child: SizedBox(
1243	        height: DesignTokens.audioWaveformHeight,
1244	        child: Row(
1245	          mainAxisAlignment: MainAxisAlignment.center,
1246	          crossAxisAlignment: CrossAxisAlignment.center,
1247	          children: [
1248	            for (var i = 0; i < _samples.length; i++) ...[
1249	              AnimatedContainer(
1250	                duration: DesignTokens.durationSheetUp,
1251	                width: DesignTokens.audioWaveformBarWidth,
1252	                height: DesignTokens.audioWaveformHeight * _samples[i],
1253	                decoration: const BoxDecoration(
1254	                  // Prototype: the bars themselves are `colorSecondary`
1255	                  // (olive green) — only the recording timer text is
1256	                  // `colorError` (correction; a previous pass swapped the
1257	                  // two). A small, fixed corner radius (not [radiusFull])
1258	                  // keeps every bar reading as a bar rather than a dot at
1259	                  // low amplitude.
1260	                  color: DesignTokens.colorSecondary,
1261	                  borderRadius: BorderRadius.all(
1262	                    Radius.circular(DesignTokens.audioWaveformBarRadius),
1263	                  ),
1264	                ),
1265	              ),
1266	              if (i < _samples.length - 1)
1267	                const SizedBox(width: DesignTokens.audioWaveformBarGap),
1268	            ],
1269	          ],
1270	        ),
1271	      ),
1272	    );
1273	  }
1274	}
