/// Covers all 3 [PhotoErrorKind] branches (I/O matrix): `ocrNoText`'s two
/// recovery paths, `payloadTooLarge`'s "pick a different photo" only, and
/// `generic`'s OCR-call-retry vs. save-failure-editable-field split
/// (Design Notes: "a discriminator is clearer than overloading
/// nullability tricks").
class _PhotoErrorView extends StatelessWidget {
  const _PhotoErrorView({required this.controller, required this.state});

  final TextEditingController controller;
  final PhotoError state;

  @override
  Widget build(BuildContext context) {
    switch (state.kind) {
      case PhotoErrorKind.ocrNoText:
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            _PhotoThumbnail(
              path: state.path,
              width: DesignTokens.photoThumbnailLargeWidth,
              height: DesignTokens.photoThumbnailLargeHeight,
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            const Icon(Icons.error_outline, color: DesignTokens.colorError),
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              state.message,
              textAlign: TextAlign.center,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            Row(
              children: [
                Expanded(
                  child: AppButton(
                    label: 'Tentar novamente',
                    onPressed: () => context.read<PhotoEntryCubit>().retry(),
                  ),
                ),
                const SizedBox(width: DesignTokens.spacingSm),
                Expanded(
                  child: AppButton(
                    label: 'Salvar só a foto',
                    variant: AppButtonVariant.secondaryOutline,
                    onPressed: () =>
                        context.read<PhotoEntryCubit>().saveWithoutText(),
                  ),
                ),
              ],
            ),
          ],
        );

      case PhotoErrorKind.payloadTooLarge:
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.error_outline, color: DesignTokens.colorError),
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              state.message,
              textAlign: TextAlign.center,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            const _PhotoCaptureButtons(),
          ],
        );

      case PhotoErrorKind.generic:
        if (state.text == null) {
          return Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.error_outline, color: DesignTokens.colorError),
              const SizedBox(height: DesignTokens.spacingSm),
              Text(
                state.message,
                textAlign: TextAlign.center,
                style: DesignTokens.textBodyMd.copyWith(
                  color: DesignTokens.colorError,
                ),
              ),
              const SizedBox(height: DesignTokens.spacingMd),
              AppButton(
                label: 'Tentar novamente',
                onPressed: () => context.read<PhotoEntryCubit>().retry(),
              ),
            ],
          );
        }
        final canSave = controller.text.trim().isNotEmpty;
        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // Same side-by-side layout as `_PhotoRecognizedView` — this
            // branch is a save failure on otherwise-recognized text, not a
            // distinct prototype state, so it keeps the small thumbnail
            // rather than the full-width one that caused the overflow this
            // correction fixes.
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _PhotoThumbnail(
                  path: state.path,
                  width: DesignTokens.photoThumbnailSmallSize,
                  height: DesignTokens.photoThumbnailSmallSize,
                ),
                const SizedBox(width: DesignTokens.photoRecognizedGap),
                Expanded(
